head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70001_create";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.goWrite((dma_report.get("formCd") ?? (() => { throw new Error("unresolved:" + "dma_report.formCd"); })()), (dma_report.get("formVer") ?? (() => { throw new Error("unresolved:" + "dma_report.formVer"); })()), '' + dma_report.get("formAdmInstTpCd") + '', '' + dma_report.get("inqdisclsTpCd") + '', '0', (dma_report.get("formUpclssCd") ?? (() => { throw new Error("unresolved:" + "dma_report.formUpclssCd"); })()), (dma_report.get("rsnClssCd") ?? (() => { throw new Error("unresolved:" + "dma_report.rsnClssCd"); })()), '' + dma_report.get("applFormYn") + '', (dma_report.get("ldMktTpCd") ?? (() => { throw new Error("unresolved:" + "dma_report.ldMktTpCd"); })()), '' + dma_report.get("formWrtMethdTpCd") + '', '' + dma_report.get("byformUsrTpCd") + '', (dma_report.get("exmptObjDisclsYn") ?? (() => { throw new Error("unresolved:" + "dma_report.exmptObjDisclsYn"); })()), '' + dma_report.get("ismulti") + '', '' + dma_report.get("editClssCd") + '', '' + dma_report.get("disclsWrtObjYn") + '');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70001_create.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70001_create.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_69_onsubmit
 * @description form_69 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_69_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70001_create.form_69_onsubmit' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_registerDisclosureAction
 * @description register Disclosure Action 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_registerDisclosureAction = async function () {
    const sbmOptions = {
        id: "tx_registerDisclosureAction",
        method: "post",
        action: "/discls/disclosurereg.do?method=registerDisclosure",
        ref: "dma_registerDisclosureActionReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_documentWrite
 * @description document Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_documentWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_documentWrite",
        method: "post",
        action: "/discls/disclosure.do?method=disclosureCreate",
        ref: "dma_documentWriteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_goAction
 * @description go Action 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goAction = async function () {
    const sbmOptions = {
        id: "tx_goAction",
        method: "post",
        action: "/submission/disclosure.do?method=createDartFormPreview",
        ref: "dma_goActionReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_checkServiced
 * @description check Serviced 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_checkServiced = async function () {
    const sbmOptions = {
        id: "tx_checkServiced",
        method: "post",
        action: "/discls/checkServiced.do",
        ref: "dma_checkServicedReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name registerDisclosureAction
 * @description register Disclosure Action 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerDisclosureAction = async function () {
    (document.disclosureFrm || { elements: [] }).action = '/discls/disclosurereg.do?method=registerDisclosure';
    (document.disclosureFrm || { elements: [] }).target = 'tempSaveFrame';
    await scwin.tx_registerDisclosureAction();
};

/**
 * @method
 * @name documentWrite
 * @description document Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentWrite = async function () {
    (document.writeForm || { elements: [] }).action = '/discls/disclosure.do?method=disclosureCreate';
    await scwin.tx_fn_documentWrite();
};

/**
 * @method
 * @name registerProcess
 * @description register Process 처리
 * @param {*} applNo applNo
 * @param {*} docNo docNo
 * @param {String} ipt_formCd ipt_formCd
 * @param {*} formVer formVer
 * @param {String} wrtrptMaindocTpCd wrtrptMaindocTpCd
 * @param {*} method method
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerProcess = async function (applNo, docNo, ipt_formCd, formVer, wrtrptMaindocTpCd, method) {
    $c.util.getComponent('dma_registerDisclosureActionReq').set('applNo', applNo);
    if (applNo.length === 14) {
        await scwin.documentWrite();
    } else {
        await scwin.registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
};

/**
 * @method
 * @name registerMessage
 * @description register Message 처리
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerMessage = async function (msg) {
    await alertE(msg);
};

/**
 * @method
 * @name goAction
 * @description go Action 처리
 * @param {String} ipt_formCd ipt_formCd
 * @param {*} formVer formVer
 * @param {String} formAdmInstTpCd formAdmInstTpCd
 * @param {String} inqdisclsTpCd inqdisclsTpCd
 * @param {String} langTpCd langTpCd
 * @param {String} formUpclssCd formUpclssCd
 * @param {String} rsnClssCd rsnClssCd
 * @param {String} applFormYn applFormYn
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {String} formWrtMethdTpCd formWrtMethdTpCd
 * @param {String} byFormUsrTpCd byFormUsrTpCd
 * @param {String} exmptObjDisclsYn exmptObjDisclsYn
 * @param {*} isMulti isMulti
 * @param {String} editClssCd editClssCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goAction = async function (ipt_formCd, formVer, formAdmInstTpCd, inqdisclsTpCd, langTpCd, formUpclssCd, rsnClssCd, applFormYn, ldMktTpCd, formWrtMethdTpCd, byFormUsrTpCd, exmptObjDisclsYn, isMulti, editClssCd) {
    if (formAdmInstTpCd === "1") {
        await scwin.goWrite(ipt_formCd, formVer, formAdmInstTpCd, inqdisclsTpCd, langTpCd, formUpclssCd, rsnClssCd, applFormYn, ldMktTpCd, formWrtMethdTpCd, byFormUsrTpCd, exmptObjDisclsYn, isMulti, editClssCd);
    } else {
        if (formAdmInstTpCd === "2") {
            ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_formCd', ipt_formCd) : console.warn('[sdd] hiddenStore 부재: ipt_formCd'));
            await scwin.tx_goAction();
        }
    }
};

/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @param {String} ipt_formCd ipt_formCd
 * @param {*} formVer formVer
 * @param {String} formAdmInstTpCd formAdmInstTpCd
 * @param {String} inqdisclsTpCd inqdisclsTpCd
 * @param {String} langTpCd langTpCd
 * @param {String} formUpclssCd formUpclssCd
 * @param {String} rsnClssCd rsnClssCd
 * @param {String} applFormYn applFormYn
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {String} formWrtMethdTpCd formWrtMethdTpCd
 * @param {String} byFormUsrTpCd byFormUsrTpCd
 * @param {String} exmptObjDisclsYn exmptObjDisclsYn
 * @param {*} isMulti isMulti
 * @param {String} editClssCd editClssCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function (ipt_formCd, formVer, formAdmInstTpCd, inqdisclsTpCd, langTpCd, formUpclssCd, rsnClssCd, applFormYn, ldMktTpCd, formWrtMethdTpCd, byFormUsrTpCd, exmptObjDisclsYn, isMulti, editClssCd) {
    await scwin.goWriteNext(ipt_formCd, formVer, formAdmInstTpCd, inqdisclsTpCd, langTpCd, formUpclssCd, rsnClssCd, applFormYn, ldMktTpCd, formWrtMethdTpCd, byFormUsrTpCd, exmptObjDisclsYn, isMulti, editClssCd);
};

/**
 * @method
 * @name goWriteNext
 * @description go Write Next 처리
 * @param {String} ipt_formCd ipt_formCd
 * @param {*} formVer formVer
 * @param {String} formAdmInstTpCd formAdmInstTpCd
 * @param {String} inqdisclsTpCd inqdisclsTpCd
 * @param {String} langTpCd langTpCd
 * @param {String} formUpclssCd formUpclssCd
 * @param {String} rsnClssCd rsnClssCd
 * @param {String} applFormYn applFormYn
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {String} formWrtMethdTpCd formWrtMethdTpCd
 * @param {String} byFormUsrTpCd byFormUsrTpCd
 * @param {String} exmptObjDisclsYn exmptObjDisclsYn
 * @param {*} isMulti isMulti
 * @param {String} editClssCd editClssCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWriteNext = async function (ipt_formCd, formVer, formAdmInstTpCd, inqdisclsTpCd, langTpCd, formUpclssCd, rsnClssCd, applFormYn, ldMktTpCd, formWrtMethdTpCd, byFormUsrTpCd, exmptObjDisclsYn, isMulti, editClssCd) {
    $c.util.getComponent('dma_registerDisclosureActionReq').set('disclsMaindocFormCd', ipt_formCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('disclsMaindocFormVer', formVer);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('formCd', ipt_formCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('formVer', formVer);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('langTpCd', langTpCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('formUpclssCd', formUpclssCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('rsnClssCd', rsnClssCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('ldMktTpCd', ldMktTpCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('disclsMaindocFormCd', ipt_formCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('disclsMaindocFormVer', formVer);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('formCd', ipt_formCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('formVer', formVer);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('langTpCd', langTpCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('formUpclssCd', formUpclssCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('rsnClssCd', rsnClssCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('ldMktTpCd', ldMktTpCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('exmptObjDisclsYn', exmptObjDisclsYn);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('exmptObjDisclsYn', exmptObjDisclsYn);
    const inqOrgnDisclsAcptNo = '' + dma_report.get("inqOrgnDisclsAcptNo") + '';
    if (null !== inqOrgnDisclsAcptNo && '' !== inqOrgnDisclsAcptNo) {
        $c.util.getComponent('dma_registerDisclosureActionReq').set('disclsModAddTpCd', 'Q');
        $c.util.getComponent('dma_registerDisclosureActionReq').set('inqOrgnDisclsAcptNo', inqOrgnDisclsAcptNo);
    }
    let acptApplTpCd = 'D';
    if (applFormYn === 'Y') {
        acptApplTpCd = 'L';
    }
    if ('99602' === ipt_formCd || '99603' === ipt_formCd) {
        const isExaServiced = await scwin.checkServiced("ETC06");
        $c.util.getComponent('dma_registerDisclosureActionReq').set('isExaServiced', isExaServiced);
        $c.util.getComponent('dma_registerDisclosureActionReq').set('isExaServiced', isExaServiced);
        if (isExaServiced !== "Y") {
            if (!await $c.win.confirm("현재 일부 시스템에 오류가 발생하여 공시문서 작성 후 임시저장만 가능하며 제출은 불가합니다. 계속하시겠습니까?")) {
                return;
            }
        }
    }
    $c.util.getComponent('dma_registerDisclosureActionReq').set('acptApplTpCd', acptApplTpCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('acptApplTpCd', acptApplTpCd);
    $c.util.getComponent('dma_registerDisclosureActionReq').set('exmptObjDisclsYn', exmptObjDisclsYn);
    await scwin.registerDisclosureAction();
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name checkServiced_done
 * @description check Serviced done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.checkServiced_done = function (data) {
    checkResult = (typeof data === "string" ? JSON.parse(data) : data).isServiced;
};

/**
 * @method
 * @name checkServiced
 * @description check Serviced 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkServiced = async function () {
    const r = await scwin.tx_checkServiced();
    try {
        scwin.checkServiced_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldods70001_create.checkServiced' });
    }
    return r;
};
